#include "stdlib/math/base/special/log1mexpf.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/expm1f.h"
#include "stdlib/math/base/special/expf.h"
#include "stdlib/math/base/special/log1pf.h"
#include "stdlib/math/base/special/lnf.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/constants/float32/ninf.h"
#include "stdlib/constants/float32/ln_two.h"

/**
* Computes the natural logarithm of `1-exp(-|x|)` for a single-precision floating-point number.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_log1mexpf( 5.0f );
* // returns ~-0.00676f
*/
float stdlib_base_log1mexpf( const float x ) {
	float ax;
	if ( stdlib_base_is_nanf( x ) ) {
		return x;
	}
	if ( x == 0.0f ) {
		return STDLIB_CONSTANT_FLOAT32_NINF;
	}
	ax = stdlib_base_absf( x );
	if ( 0.0f < ax && ax <= STDLIB_CONSTANT_FLOAT32_LN2 ) {
		return stdlib_base_lnf( -stdlib_base_expm1f( -ax ) );
	}
	// Case: |x| > ln(2)
	return stdlib_base_log1pf( -stdlib_base_expf( -ax ) );
}
